return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Lithuanian','last-translator' => 'Diego Versiani','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=3; plural=(n%10==1 && (n%100<11 || n%100>19) ? 0 : n%10>=2 && (n%100<11 || n%100>19) ? 1 : 2);','po-revision-date' => '2025-04-28 12:19+0000','language' => 'lt_LT','x-generator' => 'Loco https://localise.biz/','x-loco-version' => '2.7.2; wp-6.8','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Eikite į Įskiepių paieška','Activate %s' => 'Suaktyvinti %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> reikalauja, kad būtų įdiegta ir aktyvuota <strong>%2$s</strong>. <a href="%4$s">%3$s</a>','Enter your code here' => 'Įveskite savo kodą čia','Add %s' => 'Pridėti %s','Remove' => 'Pašalinti','Order number and receipt will be sent to this email address.' => 'Šiuo el. pašto adresu bus išsiųstas užsakymo numeris ir kvitas.','Apartment, unit, building, floor, etc.' => 'Butas, vienetas, pastatas, aukštas ir t. t.','Shipping phone' => 'Siuntimo telefonas','Only used for shipping-related questions.' => 'Naudojama tik su siuntimu susijusiems klausimams.','Single step' => 'Vienas žingsnis','Click to go to the order summary' => 'Spustelėkite, jei norite pereiti į užsakymo santrauką','Cart total:' => 'Iš viso krepšelio:','Proceed to %s' => 'Pereiti prie %s','Proceed to contact' => 'Pereikite prie kontaktų','Proceed to shipping' => 'Pereiti prie siuntimo','Proceed to billing' => 'Pereiti prie sąskaitų išrašymo','Proceed to payment' => 'Pereiti prie mokėjimo','Shipping method' => 'Pristatymo būdas','Additional notes' => 'Papildomos pastabos','Payment method' => 'Mokėjimo būdas','Step %1$s of %2$s' => 'Žingsnis %1$s iš %2$s','Change: %s' => 'Pakeitimai: %s','Not selected yet.' => 'Dar nepasirinktas.','Same as shipping address' => 'Toks pat kaip pristatymo adresas','Same as billing address' => 'Toks pat kaip ir sąskaitos išrašymo adresas','Order summary' => 'Užsakymo santrauka','Edit cart' => 'Redaguoti krepšelį','Did you mean %s?' => 'Ar turėjote omenyje %s?','Change email address to: {suggestion-value}' => 'Pakeiskite el. pašto adresą į: {suggestion-value}','This is a required field.' => 'Tai privalomas laukas.','This is not a valid email address.' => 'Tai nėra galiojantis el. pašto adresas.','This field does not match the related field value.' => 'Šis laukas neatitinka susijusio lauko vertės.','The CPF number "{cpf_number}" is invalid.' => 'CPF numeris "{cpf_number}" negalioja.','The CNPJ number "{cnpj_number}" is invalid.' => 'CNPJ numeris "{cnpj_number}" negalioja.','(Required)' => '(privaloma)','Checkout Header - Desktop' => 'Kasos antraštė - darbalaukis','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Rodykite valdiklius kasos antraštėje dideliems ekranams. Rodoma tik jei naudojama įskiepio kasos antraštė.','Checkout Header - Mobile' => 'Kasos antraštė - Mobilioji','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Rodyti valdiklius po kasos antraštės mobiliesiems įrenginiams. Rodoma tik jei naudojama įskiepio kasos antraštė.','Checkout Sidebar' => 'Kasos šoninė juosta','Display widgets on the checkout sidebar after the order summary.' => 'Rodyti valdiklius kasos šoninėje juostoje po užsakymo santraukos.','Checkout Order Summary' => 'Kasos užsakymo santrauka','Display widgets inside the order summary at the checkout page.' => 'Rodyklės rodomos užsakymo santraukos viduje kasos puslapyje.','Checkout Below Place Order' => 'Atsiskaitymas žemiau Užsakymo vieta','Display widgets below the place order button at the checkout page.' => 'Rodyti valdiklius po užsakymo pateikimo mygtuku kasos puslapyje.','Checkout Footer' => 'Kasos poraštė','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Rodyti valdiklius kasos apačioje. Rodoma tik jei naudojamas įskiepio kasos poraštė.','Classic' => 'Klasikinis','Boxed' => 'Dėžutėje','Split' => 'Splitas','Minimalist' => 'Minimalistinis','Fluid Checkout and Delivery Date plugins by CodeRockz' => '"CodeRockz" įskiepiai "Fluid Checkout" ir "Delivery Date','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>Nustatėme, kad naudojate "CodeRockz" įskiepius "Delivery & Pickup Date Time for WooCommerce" (nemokamus ir PRO). Integracija su šiais įskiepiais buvo perkelta į "Fluid Checkout PRO".</p>','Upgrade to PRO' => 'Atnaujinti į PRO','Fluid Checkout database updated successfully' => 'Sėkmingai atnaujinta "Fluid Checkout" duomenų bazė','The database changes where applied successfully.' => 'Duomenų bazės pakeitimai sėkmingai pritaikyti.','Dismiss' => 'Atmesti','Fluid Checkout database update' => '"Fluid Checkout" duomenų bazės atnaujinimas','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Reikia atlikti tam tikrus duomenų bazės pakeitimus. Kaip ir bet kokio atnaujinimo atveju, rekomenduojame prieš atliekant atnaujinimą <strong>padaryti atsarginę svetainės kopiją</strong>.','Update database' => 'Duomenų bazės atnaujinimas','Fluid Checkout is not compatible with the Divi Builder checkout layout' => '"Fluid Checkout" nėra suderinamas su "Divi Builder" kasos išdėstymu','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p> Kad veiktų "Fluid Checkout", reikia, kad veiktų klasikinė "WooCommerce" trumpaisiais kodais pagrįsta kasos forma. Naudojant "Divi Builder" kasos puslapio išvaizdai pritaikyti, klasikiniai trumpieji kodai pakeičiami pasirinktiniais "Divi Builder" valdikliais, skirtais kiekvienai kasos puslapio daliai. Šie pasirinktiniai valdikliai nesuderinami su "Fluid Checkout".</p><p>Prašome redaguoti kasos puslapį, pakeičiant "Divi Builder" valdiklius tekstiniu valdikliu, kuriame yra trumpasis kodas <code>[woocommerce_checkout]</code>.</p>','Edit the checkout page' => 'Redaguoti kasos puslapį','Read the documentation.' => 'Skaitykite dokumentus.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Naudojant "Fluid Checkout" reikia išjungti "Germanized PRO" kelių etapų kasos funkciją','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Naudojant "Fluid Checkout", "Germanized PRO" įskiepio kelių etapų funkcija tampa nereikalinga ir gali sukelti <strong>kritinių klaidų apdorojant naujus užsakymus</strong>. Įskiepio "Germanized PRO" daugiapakopio užsakymo funkciją išjunkite įskiepio nustatymuose.','Go to Germanized settings' => 'Pereikite prie germanizuotų nustatymų','Thanks for choosing Fluid Checkout!' => 'Ačiū, kad pasirinkote "Fluid Checkout"!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Jau kurį laiką naudojate įskiepį. Kaip jums kol kas jis patinka? <br>Prašome trumpai įvertinti, vertiname kiekvieną atsiliepimą ir tai mus skatina toliau tobulinti įskiepį :)','Rate the plugin' => 'Įvertinkite įskiepį','I need help!' => 'Man reikia pagalbos!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'Kai kurios "WooCommerce" kasos tvarkyklės funkcijos gali neveikti taip, kaip tikėtasi, kai ją naudojate su "Fluid Checkout". Daugiau informacijos ir alternatyvių sprendimų rasite <a href="%s">mūsų dokumentacijoje</a>.','Read documentation' => 'Skaityti dokumentus','Don\'t show this again' => 'Daugiau to nerodykite','Fluid Checkout PRO' => 'Fluid Checkout PRO','More design templates' => 'Daugiau dizaino šablonų','Optimized cart page' => 'Optimizuotas krepšelio puslapis','Optimized order received / thank you page' => 'Optimizuotas gauto užsakymo / padėkos puslapis','Edit cart contents at checkout page' => 'Redaguoti krepšelio turinį kasos puslapyje','Account matching / user matching' => 'Paskyros atitikimas / naudotojo atitikimas','Trust symbols on the cart and thank you pages' => 'Pasitikėjimo simboliai krepšelyje ir padėkos puslapiuose','More positions for the coupon code on the checkout page' => 'Daugiau pozicijų kupono kodą kasos puslapyje','International phone numbers' => 'Tarptautiniai telefono numeriai','Gift messages and packing slips' => 'Dovanų pranešimai ir pakavimo lapeliai','Local pickup and in-store collection' => 'Vietinis paėmimas ir surinkimas parduotuvėje','EU-VAT Assistant' => 'ES PVM mokėtojo padėjėjas','I already have it – Hide this offer' => 'Jau turiu - Paslėpti šį pasiūlymą','Activated' => 'Aktyvuota','Address book' => 'Adresų knyga','Select an image' => 'Pasirinkite vaizdą','Cart layout' => 'Krepšelio išdėstymas','Cart optimizations' => 'Krepšelio optimizavimas','Enable cart page optimizations' => 'Įgalinti krepšelio puslapio optimizavimą','Header and footer template' => 'Antraštės ir poraštės šablonas','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Nustato, ar naudoti puslapio antraštę ir poraštę, ar išlaikyti šiuo metu aktyvios temos antraštę ir poraštę.','Distraction free header and footer' => 'Neblaškanti antraštė ir poraštė','Theme\'s header and footer' => 'Temos antraštė ir poraštė','Cart elements' => 'Krepšelio elementai','Make the order summary stay visible on the cart page while scrolling' => 'Užtikrinkite, kad užsakymo santrauka būtų matoma krepšelio puslapyje slinkimo metu','Coupon codes' => 'Kuponų kodai','Hidden' => 'Paslėptas','Before the cart items section' => 'Prieš krepšelio elementų skiltį','Inside the cart items section' => 'Krepšelio elementų skilties viduje','After the cart items section' => 'Po krepšelio elementų skilties','Before the shipping section' => 'Prieš siuntimo skyrių','After the shipping section' => 'Po pristatymo skyriaus','Before the order summary' => 'Prieš užsakymo santrauką','Inside the order summary' => 'Užsakymo santraukos viduje','Before the order totals' => 'Prieš užsakymo sumas','After the order totals' => 'Po užsakymo sumų','After the order summary' => 'Po užsakymo santraukos','Shipping' => 'Pristatymas','Select position where to display the shipping costs and calculator on the cart page.' => 'Pasirinkite poziciją, kurioje bus rodomos pristatymo išlaidos ir skaičiuoklė krepšelio puslapyje.','Display as a cart section' => 'Rodyti kaip krepšelio skyrių','Cross-sells' => 'Kryžminiai pardavimai','Select position where to display the cross-sells section on the cart page.' => 'Pasirinkite vietą, kurioje bus rodomas kryžminių pardavimų skyrius krepšelio puslapyje.','Before the cart actions' => 'Prieš krepšelio veiksmus','After the cart actions' => 'Po krepšelio veiksmų','Layout of cross-sell items on the cart page.' => 'Kryžminio pardavimo elementų išdėstymas krepšelio puslapyje.','Optimized horizontal cross-sells layout' => 'Optimizuotas horizontalių kryžminių pardavimų išdėstymas','Theme\'s cross-sells layout' => 'Temos kryžminių pardavimų išdėstymas','Number of cross-sell items to display on the cart page' => 'Kryžminio pardavimo elementų, rodomų krepšelio puslapyje, skaičius','Add widget areas to the cart page' => 'Į krepšelį pridėkite valdiklių sričių','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Šios valdiklių sritys naudojamos pasitikėjimo simboliams ir pasitikėjimo ženkliukams krepšelio puslapyje pridėti.','Checkout' => 'Kasa','Checkout layout' => 'Registracijos išdėstymas','Design template' => 'Dizaino šablonas','Dark mode' => 'Tamsusis režimas','Enable dark mode' => 'Įjungti tamsųjį režimą','Logo image' => 'Logotipo vaizdas','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'Pasirinkite vaizdą, kuris bus rodomas kasos puslapio antraštėje. Taikoma tik tada, kai naudojate antraštę ir poraštę, neblaškančią dėmesio.','Header background color' => 'Antraštės fono spalva','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Pasirinkite kasos puslapio antraštės fono spalvą. Taikoma tik tada, kai naudojama neblaškanti antraštė ir poraštė.','HTML color value. ie: #f3f3f3' => 'HTML spalvos reikšmė. t. y: #f3f3f3f3','Page background color' => 'Puslapio fono spalva','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Pasirinkite kasos puslapio fono spalvą. Spalva taikoma elementui <em>body</em>.','Footer background color' => 'Fono spalva','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Pasirinkite kasos puslapio poraštės fono spalvą. Taikoma tik tada, kai naudojate antraštę ir poraštę, neblaškančią dėmesio.','Progress bar' => 'Pažangos juosta','Display the checkout progress bar when using multi-step checkout layout' => 'Kasos eigos juostos rodymas, kai naudojamas kelių etapų kasos išdėstymas','Make the checkout progress bar stay visible while scrolling' => 'Užtikrinkite, kad kasos eigos juosta liktų matoma slinkimo metu','Express checkout' => 'Skubus išrašymas','Enable the express checkout section' => 'Įgalinkite greitojo užsakymo skyrių','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Kai palaikomuose mokėjimo vartuose ši funkcija įjungta, kasoje rodomas skubaus atsiskaitymo skyrius.','Display express checkout buttons in one line for larger screens' => 'Didesniuose ekranuose rodykite greitojo užsakymo mygtukus vienoje eilutėje','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'Ignoruoti papildomus privalomus kasos laukus, kai mokate naudodami suderinamus greitojo mokėjimo vartus.','Make the order summary stay visible while scrolling' => 'Užtikrinkite, kad užsakymo santrauka liktų matoma slinkimo metu','Choose a background color for the order summary section.' => 'Pasirinkite užsakymo santraukos skyriaus fono spalvą.','Highlight the order totals row in the order summary table' => 'Pažymėkite užsakymų suvestinės lentelės užsakymų sumų eilutę','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Naudingiausia, kai užsakymo santraukos skyriuje nėra paryškintos fono spalvos. Taip pat gali būti taikoma krepšelio, gauto užsakymo ir užsakymo peržiūros puslapiams, kai naudojamas "Fluid Checkout PRO".','Action link on the order summary at checkout.' => 'Veiksmo nuoroda užsakymo santraukoje prie kasos.','Edit cart link' => 'Redaguoti krepšelio nuorodą','Cart items count' => 'Krepšelio elementų skaičius','Link to shop page' => 'Nuoroda į parduotuvės puslapį','Cart items' => 'Krepšelio elementai','Hide cart items errors at the checkout page' => 'Paslėpti krepšelio elementų klaidas kasos puslapyje','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'Kasos puslapio viršuje nerodykite pranešimo apie krepšelio elementų klaidas. Kai pateiksite kasos formą pirkiniui užbaigti, šie klaidų pranešimai bus rodomi visada.','Place order' => 'Pateikite užsakymą','Define the position to display "Place order" and terms checkbox section.' => 'Nustatykite vietą, kurioje bus rodomas "Place order" ir sąlygų žymimojo langelio skyrius.','Some options might not be compatible with some plugins and themes.' => 'Kai kurios parinktys gali būti nesuderinamos su kai kuriais įskiepiais ir temomis.','Below the payment section' => 'Po mokėjimo skiltimi','Below the order summary' => 'Žemiau pateikiama užsakymo santrauka','Both below the payment section and the order summary' => 'Tiek po mokėjimo skiltimi, tiek po užsakymo santrauka','Add widget areas to the checkout page' => 'Į kasos puslapį įtraukite valdiklių sritis','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Šios valdiklių sritys naudojamos pasitikėjimo simboliams ir pasitikėjimo ženkliukams kasos puslapyje pridėti.','Display the coupon codes section title' => 'Rodyti kuponų kodų skyriaus pavadinimą','Select position where to display the coupon codes section on the checkout page.' => 'Pasirinkite poziciją, kurioje rodyti kuponų kodų skyrių kasos puslapyje.','Before the checkout steps' => 'Prieš kasos veiksmus','As a substep before payment methods' => 'Kaip papildomas žingsnis prieš mokėjimo metodus','As a substep after payment methods' => 'Po mokėjimo metodų atliekamas papildomas etapas','Default button style' => 'Numatytojo mygtuko stilius','"Add" link button' => '"Pridėti" nuorodos mygtukas','Checkout fields' => 'Kasos laukai','Optional fields' => 'Neprivalomi laukai','Hide optional fields behind a link button' => 'Neprivalomų laukų slėpimas už nuorodos mygtuko','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'Rekomenduojama palikti šią parinktį pažymėtą, kad sumažėtų atvirų įvesties laukų skaičius, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">skaitykite tyrimą</a>.','Do not hide "Address line 2" fields behind a link button' => 'Neslėpkite laukų "Adreso eilutė 2" už nuorodos mygtuko','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Rekomenduojama tik tada, kai daugumai klientų iš tikrųjų reikia lauko "Adreso 2 eilutė" arba kai labai svarbu nurodyti teisingą pristatymo adresą (pvz., jei pristatomas maistas ir kiti greitai gendantys produktai).','Billing address' => 'Atsiskaitymo adresas','Select position where to display the billing address section on the checkout page.' => 'Pasirinkite vietą, kurioje kasos puslapyje bus rodomas atsiskaitymo adreso skyrius.','As a step before shipping' => 'Prieš išsiunčiant','As a sub-step before the shipping address section' => 'Kaip antrinis žingsnis prieš siuntimo adreso skiltį','As a sub-step after the shipping address section' => 'Po pristatymo adreso skilties kaip papildomas žingsnis','As a step after shipping' => 'Kaip etapas po siuntimo','As a sub-step before the payment section' => 'Kaip papildomas etapas prieš mokėjimo skirsnį','Force billing and shipping addresses to the same (single section)' => 'Priversti sąskaitų išrašymo ir pristatymo adresus nurodyti tuos pačius (viename skyriuje)','Checkbox for "Same as shipping/billing address" checked by default' => 'Pagal numatytuosius nustatymus pažymėtas žymimasis langelis "Tas pats kaip pristatymo / atsiskaitymo adresas".','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'Žymimasis langelis "Same as shiping address" bus pradedamas žymėti pagal numatytuosius nustatymus, kai siuntimo adreso skiltis bus rodoma pirmą kartą. <br>Žymimasis langelis "Same as billing address" (toks pat kaip sąskaitos išrašymo adresas) bus pradedamas žymėti pagal numatytuosius nustatymus, kai pirmiausia bus rodomas sąskaitos išrašymo adreso skyrius. <br> Rekomenduojama palikti šią parinktį pažymėtą, nes taip gerokai sumažinsite atvirų įvesties laukų skaičių kasoje, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">perskaitykite tyrimą</a>.','Highlight the billing address section in the checkout form' => 'Kasos formoje paryškinkite atsiskaitymo adreso skiltį','Shipping address' => 'Pristatymo adresas','Highlight the shipping address section in the checkout form' => 'Kasos formoje paryškinkite pristatymo adreso skiltį','Shipping methods' => 'Pristatymo būdai','Choose in which position to display the shipping methods section.' => 'Pasirinkite, kurioje pozicijoje rodyti pristatymo būdų skyrių.','Before shipping address' => 'Prieš siuntimo adresą','After shipping address' => 'Po pristatymo adreso','Local pickup' => 'Vietinis paėmimas','Removes shipping address section when a local pickup shipping method is selected.' => 'Pašalinamas pristatymo adreso skyrius, kai pasirinktas vietinio atsiėmimo pristatymo būdas.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'Pakeičia pristatymo adresą į paėmimo vietos vietą, kai pasirinktas vietinio paėmimo pristatymo būdas.','Choose which address to save as the shipping address for local pickup orders.' => 'Pasirinkite, kurį adresą išsaugoti kaip pristatymo adresą vietinio atsiėmimo užsakymams.','Save the selected pickup location' => 'Išsaugoti pasirinktą paėmimo vietą','Save same as the billing address' => 'Išsaugoti tą patį kaip ir sąskaitos išrašymo adresas','Do not save any shipping address' => 'Neišsaugokite jokio pristatymo adreso','Company name field for shipping address' => 'Įmonės pavadinimo laukas, skirtas pristatymo adresui','Change visibility for the company name field for the shipping address section on the checkout form.' => 'Pakeiskite įmonės pavadinimo lauko matomumą kasos formos pristatymo adreso skiltyje.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Jei laukas nustatytas kaip "neprivalomas", o tai yra numatytoji matomumo būsena, jokie pakeitimai nebus taikomi, kad kiti įskiepiai galėtų taikyti reikiamus pakeitimus.','Hidden (remove field)' => 'Paslėpta (pašalinti lauką)','Optional' => 'Pasirinktinai','Required' => 'Reikalinga','Add shipping phone field to the checkout form.' => 'Į kasos formą įtraukite pristatymo telefono lauką.','Choose in which step to display the shipping phone field.' => 'Pasirinkite, kuriame žingsnyje rodyti pristatymo telefono lauką.','Contact step' => 'Kontaktinis žingsnis','Billing phone' => 'Atsiskaitymo telefonas','Add billing phone field to the checkout form.' => 'Į kasos formą įtraukite atsiskaitymo telefono lauką.','Choose in which step to display the billing phone field.' => 'Pasirinkite, kuriame žingsnyje rodyti sąskaitų išrašymo telefono lauką.','Show country code beside the flag' => 'Šalia vėliavos rodyti šalies kodą','Show an example of a valid phone number inside phone fields' => 'Parodykite galiojančio telefono numerio pavyzdį telefono laukuose','Do not change placeholders' => 'Nekeiskite pakaitinių žymenų','Show if not defined' => 'Rodyti, jei neapibrėžta','Always show' => 'Visada rodykite','Order notes' => 'Užsakymo pastabos','Define the visibility of the additional order notes field.' => 'Nustatykite papildomų užsakymo pastabų lauko matomumą.','Gift options' => 'Dovanų parinktys','Allow customers to add a gift message and other gift related options to the order.' => 'Leiskite klientams prie užsakymo pridėti pranešimą apie dovaną ir kitas su dovana susijusias parinktis.','Display the gift message as part of the order details table instead of a separate section' => 'Dovanos pranešimą rodyti kaip užsakymo informacijos lentelės dalį, o ne kaip atskirą skyrių','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'Ši parinktis turi įtakos užsakymo patvirtinimo puslapiui (padėkos puslapiui) ir užsakymo informacijai paskyros puslapiuose, el. laiškuose ir pakavimo lapuose.','Account matching' => 'Sąskaitų atitikimas','Enable the account matching feature' => 'Įjungti sąskaitų atitikimo funkciją','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'susieti svečio kliento užsakymus su jo esama paskyra, jei jau yra paskyra su kliento kontaktiniais duomenimis.','Display message when an account exists with the email address provided' => 'Rodyti pranešimą, kai yra paskyra su nurodytu el. pašto adresu','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'Pakeičia paskyros kūrimo laukus pranešimu ir galimybe prisijungti. Kai kuriais atvejais gali būti rekomenduojama palikti šią parinktį išjungtą, kad būtų apsaugotas klientų privatumas.','Dashboard' => 'Prietaisų skydelis','Integrations' => 'Integracijos','License keys' => 'Licencijų raktai','Visit our website for more information about our plugins and add-ons.' => 'Daugiau informacijos apie mūsų įskiepius ir priedus rasite mūsų svetainėje.','Order pay page' => 'Užsakymo apmokėjimo puslapis','Order pay' => 'Užsakymo apmokėjimas','Enable order pay page optimizations' => 'Įgalinti užsakymo apmokėjimo puslapio optimizavimą','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Pakeičia esamų užsakymų, už kuriuos klientas turi sumokėti, apmokėjimo puslapio išdėstymą.','Add widget areas to the order pay page' => 'Pridėti valdiklių sritis į užsakymo apmokėjimo puslapį','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Šios valdiklių sritys naudojamos pasitikėjimo simboliams ir pasitikėjimo ženkliukams pridėti užsakymo apmokėjimo puslapyje.','Thank you page & order details layout' => 'Ačiū puslapis ir užsakymo informacijos išdėstymas','Order details optimizations' => 'Užsakymo detalių optimizavimas','Enable thank you page and order details optimizations' => 'Įgalinkite padėkos puslapio ir užsakymo informacijos optimizavimą','Changes the layout of order details on the thank you page and account pages.' => 'Pakeistas užsakymo informacijos išdėstymas padėkos puslapyje ir paskyros puslapiuose.','Enable order details customizations on email notifications' => 'Įgalinti užsakymo detalių pritaikymą el. pašto pranešimuose','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Naujų skyrių rodymas ir skyrių eiliškumo keitimas el. pašto pranešimuose. Užsakymo informacijos stiliai el. pašto pranešimuose išlieka nepakitę.','Thank you page' => 'Ačiū puslapis','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Šios parinktys turi įtakos padėkos puslapiui, dar vadinamam gauto užsakymo arba užsakymo patvirtinimo puslapiais.','Order details layout' => 'Užsakymo informacijos išdėstymas','Display the order details with wide layout on the thank you page' => 'Rodyti užsakymo informaciją plačiu išdėstymu padėkos puslapyje','Add widget areas to the thank you page' => 'Įtraukti valdiklių sritis į padėkos puslapį','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Šios valdiklių sritys naudojamos pasitikėjimo simboliams ir pasitikėjimo ženkleliams pridėti padėkos puslapyje.','Order actions' => 'Užsakymo veiksmai','Choose in which position to display the order actions.' => 'Pasirinkite, kurioje pozicijoje rodyti užsakymo veiksmus.','Inside the order overview' => 'Užsakymo apžvalgos viduje','After the order overview' => 'Po užsakymo apžvalgos','After order sections' => 'Po užsakymo skyrių','Order status' => 'Užsakymo būsena','Display the order status progress bar' => 'Rodyti užsakymo būsenos pažangos juostą','Choose in which position to display the section.' => 'Pasirinkite, kurioje padėtyje rodyti skyrių.','After the order overview and payment instructions' => 'Po užsakymo apžvalgos ir mokėjimo nurodymų','Before the order items section' => 'Prieš užsakymo elementų skiltį','Inside the order items section' => 'Užsakymo elementų skilties viduje','After the order items section' => 'Po užsakymo elementų skilties','On the sidebar' => 'Šoninėje juostoje','Order downloads' => 'Užsakyti atsisiuntimus','Gift message' => 'Dovanų žinutė','Tools' => 'Įrankiai','Troubleshooting' => 'Trikčių šalinimas','Debug options' => 'Derinimo parinktys','Debug mode' => 'Derinimo režimas','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'Derinimo režimo naudojimas turi įtakos svetainės našumui. Šią parinktį naudokite tik trikčių šalinimo metu.','Load unminified assets' => 'Įkelti neminifikuotą turtą','Enhanced select fields' => 'Patobulinti pasirinkimo laukai','Fix automatic zoom-in on form fields' => 'Ištaisykite automatinį formos laukų priartinimą','Set <code>font-size</code> inside form fields to 16px' => 'Nustatykite <code>šrifto dydį</code> formos laukuose į 16px','Fluid Checkout' => 'Fluid Checkout','Settings' => 'Nustatymai','Support' => 'Parama','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">Atnaujinkite į PRO</a>, kad atrakintumėte daugiau parinkčių.','(PRO)' => '(PRO)','(experimental)' => '(eksperimentinis)','Please verify your phone number.' => 'Patikrinkite savo telefono numerį.','The Bluehost Plugin' => '"Bluehost" įskiepis','Custom fields' => 'Pasirinktiniai laukai','Enable custom shipping email field' => 'Įgalinti pasirinktinį pristatymo el. pašto lauką','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Įjungus šią funkciją, į kasos formą bus įtrauktas "Bluehost" įskiepio pristatymo el. pašto laukas.','Captcha Pro by BestWebSoft' => 'Captcha Pro by BestWebSoft','Captcha position' => 'Captcha pozicija','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Nustatykite vietą, kurioje bus rodomas captcha skyrius. Kai kurios pozicijos gali neveikti, priklausomai nuo pasirinkto captcha tipo.','Selecting a pickup point is required before proceeding.' => 'Prieš tęsiant darbą reikia pasirinkti paėmimo vietą.','Pickup point' => 'Pasiėmimo vieta','Pickup point not selected yet.' => 'Pasiėmimo vieta dar nepasirinkta.','Pickup point:' => 'Pasikrovimo vieta:','Mailchimp for WooCommerce' => '"Mailchimp for WooCommerce','Subscribe checkbox' => 'Prenumeratos žymimasis langelis','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'Pakeiskite prenumeratos žymimojo langelio padėtį kasos puslapyje ir visada rodykite jį kontaktų žingsnyje','Before Shipping Address' => 'Prieš siuntimo adresą','(originally "%s")' => '(iš pradžių "%s")','After Shipping Address' => 'Po pristatymo adreso','Selecting a collection point is required when shipping with FermoPoint.' => 'Siunčiant su "FermoPoint" būtina pasirinkti surinkimo vietą.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Jei pažymėta, naudotojams siunčiamuose el. laiškuose pranešama apie rašybos klaidas. (Ši funkcija buvo išjungta, nes "Fluid Checkout" siūlo šią funkciją. Šios parinkties pakeitimai neįsigalios)','Enable Mail Check: (disabled feature)' => 'Įjungti pašto patikrą: (funkcija išjungta)','Carrier:' => 'Vežėjas:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - "WooCommerce" el. pašto rinkodara','Sign up checkbox position' => 'Registracijos žymimojo langelio padėtis','Move the sign up checkbox to the contact step' => 'Perkelkite registracijos žymimąjį langelį į kontaktų žingsnį','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Kai ši funkcija įjungta, žymimasis langelis bus perkeltas į kontaktų žingsnį nepriklausomai nuo Sendinblue įskiepio nustatymuose apibrėžtos rodymo vietos.','Theme Betheme' => 'Tema Bet tema','Checkout progress' => 'Atsiskaitymo eiga','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'Išveskite kasos žingsnių skyrių iš "Betheme" kasos, krepšelio ir gauto užsakymo puslapiuose.','Theme Fennik' => 'Tema Fennik','Breadcrumbs' => 'Duonos trupiniai','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Duonos trupinių skyriaus išvedimas iš "Fennik" temos, kai naudojama "Fluid Checkout" antraštė ir poraštė.','Theme Go' => 'Tema Go','My account layout' => 'Mano paskyros išdėstymas','Enable wide layout on "My account" page.' => 'Įgalinkite platų išdėstymą puslapyje "Mano paskyra".','Theme Impreza' => 'Tema "Impreza','Header' => 'Antraštė','Spacing for site header at the checkout page (in pixels)' => 'Atstumas tarp svetainės antraštės kasos puslapyje (pikseliais)','Only applicable when using the Impreza theme header at the checkout page.' => 'Taikoma tik naudojant "Impreza" temos antraštę kasos puslapyje.','Theme Kapee' => 'Tema Kapee','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'Išveskite kasos žingsnių skyrių iš "Kapee" temos kasos, krepšelio ir gauto užsakymo puslapiuose.','Theme Porto' => 'Tema Porto','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'Išveskite kasos žingsnių skyrių iš "Porto" temos kasos, krepšelio ir gauto užsakymo puslapiuose.','Theme Pressmart' => 'Tema Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'Išveskite kasos žingsnių skyrių iš "Pressmart" temos kasos, krepšelio ir gauto užsakymo puslapiuose.','Theme The Gem' => 'Temos brangakmenis','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Išveskite kasos žingsnių skyrių iš Gem temos, kai naudojate "Fluid Checkout" antraštę ir poraštę.','Theme Woodmart' => 'Tema Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Išveskite kasos žingsnių skyrių iš Woodmart temos, kai naudojate "Fluid Checkout" antraštę ir poraštę.','Checkout options' => 'Atsiskaitymo parinktys','Disable the theme checkout options' => 'Išjungti temos kasos parinktis','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'Temos pridėtos parinktys rodyti produkto vaizdą, kiekio laukas, pašalinimo mygtukas ir nuoroda į produkto puslapį pagal numatytuosius nustatymus yra išjungtos.','Theme Atomion' => 'Tema Atomionas','Order progress' => 'Užsakymo eiga','Display order progress from the theme' => 'Rodyti užsakymo eigą iš temos','Display the form field labels visible on the page' => 'Rodyti puslapyje matomas formos laukų etiketes','It is recommended to keep this option enabled for a better user experience.' => 'Rekomenduojama palikti šią parinktį įjungtą, kad naudotojo patirtis būtų geresnė.','Theme ZK Nito' => 'Tema ZK Nito','Add extra fields to the checkout form' => 'Papildomų laukų įtraukimas į kasos formą','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'Prideda papildomą pristatymo el. pašto ir pristatymo telefono lauką į pristatymo adreso skiltį.','Go to the home page' => 'Eikite į pagrindinį puslapį','Skip to content' => 'Pereiti prie turinio','Create an account' => 'Sukurti paskyrą','Log in to your account' => 'Prisijunkite prie savo paskyros','Already have an account?' => 'Jau turite paskyrą?','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'Prisijungta kaip %1$s. <a href="%2$s">Atsijungti</a>','Your order has a total amount due of %s. No further payment is needed.' => 'Jūsų užsakymo bendra mokėtina suma yra %s. Daugiau mokėti nereikia.','Close and continue with checkout' => 'Uždarykite ir tęskite užsakymą','Continue' => 'Tęsti','Parcel terminal' => 'Siuntų terminalas','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>Šį valdiklį pakeitė "Fluid Checkout". </p><p>Kai naudojate "Fluid Checkout", kad kasos puslapis veiktų tinkamai, reikia naudoti originalųjį "WooCommerce" trumpąjį kodą <code>[woocommerce_checkout]</code>.</p><p>Daugiau informacijos rasite "Fluid Checkout" dokumentacijoje.</p>','Theme The7' => 'Tema The7','Additional header sections' => 'Papildomi antraštės skyriai','Output additional header sections if enabled in the theme settings.' => 'Išveskite papildomus antraštės skyrius, jei tai įjungta temos nustatymuose.','More information' => 'Daugiau informacijos','Pick a Locker' => 'Pasirinkite spintelę','Page template' => 'Puslapio šablonas','Use `Order confirmation` page template for block-based themes' => 'Naudokite `Užsakymo patvirtinimo` puslapio šabloną blokų pagrindu sukurtose temose','Only applies when using a block-based theme.' => 'Taikoma tik tada, kai naudojama blokais pagrįsta tema.','WooCommerce Stripe Gateway' => '"WooCommerce Stripe" vartai','Payment form' => 'Mokėjimo forma','Apply styles to the Stripe payment form fields' => 'Stilių taikymas "Stripe" mokėjimo formos laukams','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Kai ši funkcija įjungta, "Fluid Checkout" taikys stilius, optimizuotus suderinamumui su įskiepiu. Jei naudojate pasirinktinius stilius "Stripe" mokėjimo formos laukams, galite norėti tai išjungti.','Theme Nyture' => 'Tema Nyture','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Išveskite kasos žingsnių skyrių iš "Nyture" temos, kai naudojate "Fluid Checkout".','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'Leidžia klientams atlikti mokėjimus už užsakymus, kuriuos parduotuvės administratorius sukūrė rankiniu būdu arba kurie nebuvo užbaigti kasos metu.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'Quadlayers įskiepis WooCommerce Checkout Manager nėra suderinamas su Fluid Checkout','Company name field for billing address' => 'Įmonės pavadinimo laukas, skirtas atsiskaitymo adresui','Change visibility for the company name field for the billing address section on the checkout form.' => 'Pakeiskite įmonės pavadinimo lauko matomumą kasos formos atsiskaitymo adreso skiltyje.','Theme Bookshelf' => 'Teminė knygų lentyna','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'Išveskite kasos žingsnių skyrių iš "Bookshelf" temos, kai naudojate "Fluid Checkout".','Account password' => 'Paskyros slaptažodis','An account will be created with the information provided at checkout when completing the order.' => 'Paskyra bus sukurta naudojant informaciją, pateiktą kasoje užbaigiant užsakymą.','Choose the style of the progress bar.' => 'Pasirinkite progreso juostos stilių.','Bars' => 'Barai','Theme Ireca' => 'Tema Ireca','WooCommerce page layout' => '"WooCommerce" puslapio išdėstymas','Force wide layout on WooCommerce pages' => 'Priverstinis platus išdėstymas "WooCommerce" puslapiuose','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'Taip užtikrinama, kad "WooCommerce" puslapiuose, įskaitant kasos, krepšelio, gauto užsakymo, užsakymo apmokėjimo ir paskyros puslapius, turinio skiltis nebūtų per siaura.','WooCommerce Smart Coupons' => '"WooCommerce" išmanieji kuponai','Position on checkout page' => 'Pozicija kasos puslapyje','Choose where to display the available coupons section on the checkout page.' => 'Pasirinkite, kur kasos puslapyje rodyti turimų kuponų skiltį.','Before the progress bar' => 'Prieš pažangos juostą','After the progress bar' => 'Po pažangos juostos','Before coupon codes section' => 'Prieš kuponų kodų skyrių','Format phone numbers according to the rules for each country.' => 'Formuokite telefono numerius pagal kiekvienos šalies taisykles.','Use precise phone number validation' => 'Naudokite tikslų telefono numerio patvirtinimą','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'Tai yra eksperimentinė funkcija, todėl gali būti, kad ji neveiks taip, kaip tikimasi, visose konfigūracijose. Naudokite ją atsargiai.','Phone number validation types used when precise validation is enabled.' => 'Telefono numerio patvirtinimo tipai, naudojami, kai įjungtas tikslus patvirtinimas.','Mobile' => 'Mobilusis','Fixed line' => 'Fiksuotoji linija','Toll free' => 'Nemokama','Or' => 'Arba','Contact' => 'Susisiekite su','Multi step' => 'Keli žingsniai','2 columns' => '2 stulpeliai','1 column' => '1 stulpelis','Before checkout steps' => 'Veiksmai prieš išsiregistruojant','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'Naudojant <em>"1 stulpelio"</em> kasos išdėstymą, ši parinktis visada nustatoma į <em>"Prieš kasos veiksmus"</em> ir taip pat taikoma darbalaukio vaizdui.','Position for the extra order summary section on mobile.' => 'Papildomos užsakymo santraukos skilties pozicija mobiliajame telefone.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'Parinktis <em>"Svetainės antraštėje"</em> taikoma tik tada, kai naudojate antraštę, neatkreipiančią dėmesio.','On the site header (requires distraction-free header)' => 'Svetainės antraštėje (reikia, kad antraštė neblaškytų dėmesio)','Initial state for the expansible order summary section on mobile.' => 'Pradinė išplečiamo užsakymo santraukos skyriaus būsena mobiliajame telefone.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'Šiose šalyse dėl reguliavimo reikalavimų rekomenduojame jį nustatyti kaip <em>išplėstinį</em>: <strong>Vokietija</strong>, <strong>Austrija</strong>, <strong>Šveicarija</strong>, <strong>Nyderlandai</strong>, <strong>Lenkija</strong>, <strong>Belgija</strong> ir <strong>Prancūzija</strong>.','Collapsed' => 'Sugriuvęs','Expanded' => 'Išplėstas','Do not show' => 'Nerodyti','yes' => 'taip','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Laukelis „Pristatymo telefono numeris“ gali būti pažymėtas kaip „privalomas“, jei skiltis „Apskaitos adresas“ rodoma po skilties „Pristatymo adresas“, o laukas „Apskaitos telefono numeris“ yra pažymėtas kaip „privalomas“. Tai būtina siekiant užtikrinti, kad pristatymo adresas būtų nukopijuotas į apskaitos adresą, kai pažymėta atitinkama parinktis; priešingu atveju klientas gali nesugebėti užpildyti atsiskaitymo formos.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'Laukelis „Apskaitos telefono numeris“ gali būti pažymėtas kaip „privalomas“, jei skiltis „Apskaitos adresas“ rodoma prieš skiltį „Pristatymo adresas“, o laukelis „Pristatymo telefono numeris“ yra pažymėtas kaip „privalomas“. Tai būtina, kad, pažymėjus atitinkamą parinktį, pristatymo adresas būtų perkeltas į apskaitos adresą; priešingu atveju klientas gali nesugebėti užpildyti atsiskaitymo formos.','Settings profiles' => 'Nustatymų profiliai','Settings profile' => 'Nustatymų profilis','You do not have permission to perform this action.' => 'Jūs neturite leidimo atlikti šio veiksmo.','You do not have permission to activate plugins.' => 'Jūs neturite leidimo aktyvuoti papildinių.','Missing plugin.' => 'Trūksta įskiepio.','Plugin activated.' => 'Įskiepis įjungtas.','The following changes will be applied:' => 'Bus pritaikyti šie pakeitimai:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'Nuo „Fluid Checkout 5.0“ versijos nustatymai išsaugomi kitaip. Senosios parinktys vis dar saugomos duomenų bazėje, kad prireikus būtų galima grįžti prie ankstesnių versijų.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'Jūsų parduotuvė jau apie 2 savaites veikia pagal naujus nustatymus, todėl galėjote išvalyti duomenų bazėje saugomus senuosius parametrus. Atkreipkite dėmesį, kad po valymo, jei prireiks grįžti prie ankstesnių įskiepio versijų, visiems nustatymams bus naudojamos numatytosios reikšmės.','Fluid Checkout settings cleanup' => '„Fluid Checkout“ nustatymų tvarkymas','Delete leftover options' => 'Ištrinti likusius variantus','Help us improve Fluid Checkout' => 'Padėkite mums patobulinti „Fluid Checkout“','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'Dalykitės anoniminėmis svetainės aplinkos ataskaitomis su „Fluid Checkout“, kad gautumėte greitesnę pagalbą ir padėtumėte mums gerinti suderinamumą bei įvertinti poveikį. Ataskaitose nėra jokių klientų, vartotojų ar konfidencialių duomenų. „Įrankiai“ nustatymuose bet kuriuo metu galite pasirinkti, kokia informacija bus dalijamasi.','Enable site environment reports' => 'Įjungti svetainės aplinkos ataskaitas','Review settings' => 'Peržiūrėti nustatymus','This preview has expired. Reload the admin page to start a new preview.' => 'Šio peržiūros laikotarpis baigėsi. Atnaujinkite administratoriaus puslapį, kad pradėtumėte naują peržiūrą.','Preview expired' => 'Peržiūros galiojimo laikas pasibaigęs','Orders cannot be placed in the preview.' => 'Peržiūros režime užsakymų pateikti negalima.','Logging in is not available in the preview.' => 'Prisijungti per peržiūros versiją negalima.','Accounts cannot be created in the preview.' => 'Peržiūros režime negalima kurti paskyrų.','Requests to other sites are blocked in the preview.' => 'Peržiūros režime užklausos į kitas svetaines yra blokuojamos.','Processing…' => 'Apdorojama…','Something went wrong. Please try again.' => 'Įvyko klaida. Prašome bandyti dar kartą.','Activate plugin' => 'Įjunkite įskiepį','Fluid Checkout PRO - The complete checkout package' => '„Fluid Checkout PRO“ – išsamus atsiskaitymo sprendimas','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'Visos „PRO“ funkcijos + visi papildiniai už vieną kainą. Dizaino šablonai, optimizuoti pirkinių krepšelio ir užsakymo patvirtinimo puslapiai, paskyrų suderinimas ir dar daug daugiau.','Optimized order pay page' => 'Optimizuotas užsakymo apmokėjimo puslapis','Express checkout buttons from supported payment methods' => 'Greito atsiskaitymo mygtukai pagal palaikomus mokėjimo būdus','Delayed account creation' => 'Atidėtas paskyros sukūrimas','Address autocomplete with Google Maps APIs' => 'Adresų automatinis užpildymas naudojant „Google Maps“ API','Multiple saved addresses with the address book' => 'Keli išsaugoti adresai adresų knygoje','EU-VAT assistant' => 'ES PVM asistentas','Hide this section' => 'Paslėpti šį skyrių','Learn more' => 'Sužinokite daugiau','Get early access' => 'Gaukite prieigą iš anksto','Activate add-on' => 'Įjunkite papildinį','Get more out of your checkout journey' => 'Išnaudokite visas pirkimo proceso galimybes','Test API key' => 'API rakto patikrinimas','Guided setup' => 'Sąrankos vedlys','Options' => 'Parinktys','Set up layout and design on the <a href="%s">checkout options</a>.' => 'Nustatykite išdėstymą ir dizainą <a href="%s">atsiskaitymo parinktyse</a>.','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'Įjunkite galimybę atsiskaityti kaip svečiui ir (arba) peržiūrėkite <a href="%s">klientų paskyrų nustatymus</a>.','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'Įjunkite optimizuotus puslapius: <a href="%1$s">krepšelį</a>, <a href="%2$s">padėką</a> ir <a href="%3$s">užsakymo apmokėjimą</a>.','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Įjunkite <a href="%s">adresų automatinio užpildymo funkciją</a> iš „Google Maps“.','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'Įjunkite galimybę naudoti kelis išsaugotus adresus naudodami <a href="%s">adresų knygą</a>.','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Patikrinkite, ar yra kokių nors <a href="%s">integracijos galimybių</a> šiai temai ar kitiems jūsų įdiegtų įskiepių.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'Gaukite greitesnę pagalbą ir padėkite mums pagerinti suderinamumą bei įvertinti poveikį. <a href="%s">Įjunkite naudojimo stebėjimą</a> įrankių nustatymuose.','Missing settings tab.' => 'Trūksta nustatymų skirtuko.','Getting started' => 'Pradžia','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Puiku! Jūsų atsiskaitymo puslapis dabar veikia naudojant „Fluid Checkout“.</strong> Štai keli žingsniai, kaip pradėti:','Completed' => 'Užbaigta','Preview report data' => 'Ataskaitos duomenų peržiūra','Send now' => 'Siųsti dabar','Auto-detect' => 'Automatinis nustatymas','Afrikaans' => 'afrikansų kalba','Albanian' => 'Albanų','Amharic' => 'Amharų kalba','Arabic' => 'arabų kalba','Armenian' => 'Armėnų','Azerbaijani' => 'Azerbaidžaniečių','Basque' => 'baskų','Belarusian' => 'baltarusių','Bengali' => 'bengalų','Bosnian' => 'bosnių','Bulgarian' => 'Bulgarų','Burmese' => 'birmiečių','Catalan' => 'Katalonų','Chinese' => 'kinų','Chinese (Simplified)' => 'Kinų (supaprastinta)','Chinese (Hong Kong)' => 'Kinų (Honkongas)','Chinese (Traditional)' => 'Kinų (tradicinė)','Croatian' => 'Kroatų','Czech' => 'Čekija','Danish' => 'Danų','Dutch' => 'olandų','English' => 'Anglų kalba','English (Australian)' => 'Anglų (Australijos)','English (Great Britain)' => 'Anglų (Didžioji Britanija)','Estonian' => 'Estų','Farsi' => 'Farsi','Finnish' => 'Suomių','Filipino' => 'Filipinų','French' => 'prancūzų','French (Canadian)' => 'Prancūzų (Kanados)','Galician' => 'galicų','Georgian' => 'gruzinų','German' => 'vokiečių','Greek' => 'Graikų','Gujarati' => 'gudžarati','Hebrew' => 'hebrajų kalba','Hindi' => 'hindi','Hungarian' => 'Vengrų','Icelandic' => 'islandų','Indonesian' => 'Indoneziečių','Italian' => 'italų','Japanese' => 'Japonų','Kannada' => 'kanadų kalba','Kazakh' => 'kazachų','Khmer' => 'khmerų','Korean' => 'Korėjiečių','Kyrgyz' => 'Kirgizija','Lao' => 'Laosas','Latvian' => 'latvių','Lithuanian' => 'Lietuvių','Macedonian' => 'Makedonų','Malay' => 'malajų','Malayalam' => 'malajalamų kalba','Marathi' => 'maratų kalba','Mongolian' => 'mongolų','Nepali' => 'nepaliečių','Norwegian' => 'norvegų','Polish' => 'Lenkų','Portuguese' => 'portugalų','Portuguese (Brazil)' => 'Portugalų (Brazilija)','Portuguese (Portugal)' => 'Portugalų (Portugalija)','Punjabi' => 'pandžabų kalba','Romanian' => 'rumunų','Russian' => 'Rusų','Serbian' => 'Serbų','Sinhalese' => 'singalų','Slovak' => 'slovakų','Slovenian' => 'Slovėnų','Spanish' => 'ispanų','Spanish (Latin America)' => 'Ispanų (Lotynų Amerika)','Swahili' => 'svahilių kalba','Swedish' => 'Švedų','Tamil' => 'Tamilų','Telugu' => 'telugų kalba','Thai' => 'Tajų','Turkish' => 'Turkų','Ukrainian' => 'Ukrainiečių','Urdu' => 'Urdu','Vietnamese' => 'Vietnamiečių','Zulu' => 'zulų','Google address autocomplete' => '„Google“ adresų automatinis užbaigimas','Google Places API version' => '„Google Places“ API versija','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Pasirinkite, kurią „Google Places API“ versiją norite naudoti. Rekomenduojame kuo greičiau pereiti prie naujosios „Places API“ versijos.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'Rekomenduojame naudoti „Places API (New)“, nes nuo 2025 m. kovo 1 d. „Google“ perkelia „Places API (Legacy)“ versiją į „Legacy“ statusą, o tai reiškia, kad naujiems API raktams šios paslaugos įjungti nebegalėsite, o vėliau ši API versija apskritai nebeveiks. Esamos paskyros, kuriose jau naudojamas senasis API, gali toliau veikti be sutrikimų.','(Recommended)' => '(Rekomenduojama)','Google API key' => '„Google“ API raktas','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'Įklijuokite savo „Google“ API raktą ir paspauskite bandymo mygtuką, kad patikrintumėte, ar jis veikia šioje svetainėje. Įsitikinkite, kad raktas yra galiojantis ir leidžiamas jūsų domenui, nes priešingu atveju adresų laukas gali būti užblokuotas, o tai trukdytų klientams užbaigti užsakymus.','Enable Google address autocomplete' => 'Įjunkite „Google“ adresų automatinio užbaigimo funkciją','Enable address autocompletion using the Google Maps APIs.' => 'Įjunkite adresų automatinį užbaigimą naudodami „Google Maps“ API.','Google API language' => '„Google“ API kalba','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Ši kalba bus naudojama „Google Places API“ adresų pasiūlymams rodyti, be to, adresai bus automatiškai užbaigiami šia kalba.','Result types' => 'Rezultatų tipai','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Palikite tuščią, kad būtų priimami bet kokio tipo rezultatai – taip paprastai gaunami geresni atitikmenys. <a href="%s" target="_blank">Daugiau informacijos rasite dokumentacijoje</a>. <br>Pasirinkite iki 5 adresų paieškos rezultatų tipų, kurie bus rodomi adresų automatinio užpildymo laukeliuose. <br>Apsilankykite „Google Maps“ dokumentacijoje, kad sužinotumėte daugiau apie <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">palaikomus tipus</a>.','Result types (Legacy API)' => 'Rezultatų tipai (senoji API)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Kokio tipo adresų paieškos rezultatus grąžinti naudojant „Places API“ (senąją versiją). <br>Apsilankykite senosios „Google Places API“ dokumentacijoje, kad sužinotumėte daugiau apie <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">palaikomus tipus</a>.','Company fields' => 'Įmonės laukai','Enable autocomplete for the company name if available' => 'Jei įmanoma, įjunkite įmonės pavadinimo automatinio užbaigimo funkciją','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Įjunkite įmonės laukelio automatinį užpildymą, naudojant įmonės pavadinimo informaciją, gautą iš „Google Maps“ API.','Business search' => 'Įmonių paieška','Enable search for businesses in the company field' => 'Įjungti įmonių paiešką lauke „Įmonė“','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'Įjunkite su įmone susijusių adresų pasiūlymų rodymą, kai įvedate tekstą į įmonės laukelį, o pasirinkus įmonę iš pasiūlymų – automatiškai užpildykite visus adresų laukelius.','Company result types' => 'Įmonės rezultatų rūšys','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Pasirinkite iki 5 adresų paieškos rezultatų tipų, kurie bus rodomi užpildant įmonės laukelius automatinio užbaigimo funkcijos pagalba. <br>Rekomenduojama reikšmė yra <code>įmonė</code>, kuri apima daugumą verslo tipų. <br>Palikite laukelį tuščią, jei norite priimti bet kokio tipo rezultatus, įskaitant rezultatus, nesusijusius su verslu. <br>Apsilankykite „Google Maps“ dokumentacijoje, kad sužinotumėte daugiau apie <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">palaikomas rūšis</a>.','Google logo' => '„Google“ logotipas','Show text and logo "Powered by Google"' => 'Rodyti tekstą ir logotipą „Powered by Google“','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'Jei šis langelis pažymėtas, adreso automatinio užpildymo pasiūlymų langelio apačioje bus rodomas tekstas ir logotipas „Powered by Google“.','Brasil API address autocomplete' => '„Brasil API“ adresų automatinis užpildymas','Brasil API' => '„Brasil“ API','Enable Brasil API address autocomplete for CEP fields' => 'Įjungti „Brasil API“ adresų automatinio užpildymo funkciją CEP laukeliuose','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'Naudokite „Brasil API“, kad gautumėte adresus ir juos automatiškai užpildytumėte naudodami laukelį „CEP/Pašto kodas“. Tai taikoma tik Brazilijos adresams.','API version' => 'API versija','Choose which version of the Brasil API CEP method to use.' => 'Pasirinkite, kurią „Brasil API CEP“ metodo versiją norite naudoti.','Address book migration' => 'Adresų knygos perkėlimas','WooCommerce addresses' => '„WooCommerce“ adresai','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'Nukopijuokite esamus pristatymo ir sąskaitų išrašymo adresus iš „WooCommerce“ į klientų adresų knygą.','Enable the address book feature' => 'Įjunkite adresų knygos funkciją','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Suteikite klientams galimybę išsaugoti kelis adresus ir nustatyti numatytąjį adresą, kuris bus naudojamas siuntimui ir sąskaitų išrašymui.','Address labels' => 'Adresų etiketės','Allow customers to add a custom label for each address' => 'Leisti klientams pridėti individualią etiketę prie kiekvieno adreso','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'Adresų etiketės padeda klientams lengviau atskirti savo išsaugotus adresus (pvz., „Mamos namai“). Adresų etiketės yra konfidencialios ir nebus rodomos ar spausdinamos užsakymo informacijos puslapyje ar sąskaitose.','Display layout' => 'Ekrano išdėstymas','Choose how saved addresses are displayed at checkout and on the cart.' => 'Pasirinkite, kaip išsaugoti adresai bus rodomi atsiskaitant ir pirkinių krepšelyje.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'Taikoma atsiskaitant ir pirkinių krepšelyje. Paskyros puslapyje išsaugoti adresai visada rodomi kortelių išdėstymu.','Address cards' => 'Adresų kortelės','Address list' => 'Adresų sąrašas','Dropdown field' => 'Išskleidžiamasis laukas','Address search' => 'Adresų paieška','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'Rodyti adresų paieškos filtrą vartotojo sąsajoje, kai klientas turi bent šį skaičių išsaugotų adresų.','Not used when display layout is set to dropdown field.' => 'Nenaudojama, kai ekrano išdėstymas nustatytas kaip išskleidžiamas laukas.','Addresses' => 'Adresai','Enable cart page optimizations to see more options' => 'Įjunkite krepšelio puslapio optimizavimą, kad galėtumėte peržiūrėti daugiau parinkčių','Sticky order summary' => 'Fiksuota užsakymo santrauka','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Pasirinkite vietą, kurioje krepšelio puslapyje bus rodomas kuponų kodų skyrius. Ši funkcija veikia tik tada, kai įjungtas AJAX krepšelis ir jei „WooCommerce“ nustatymuose leidžiama naudoti kuponų kodus.','Layout of cross-sell' => 'Kryžminio pardavimo schema','Cross-sells displayed' => 'Rodomi susiję produktai','Items' => 'Prekės','Cart page optimization' => 'Krepšelio puslapio optimizavimas','Give your cart the same clear, conversion-focused layout as your checkout.' => 'Suteikite savo krepšeliui tokį pat aiškų, į konversiją orientuotą išdėstymą, kaip ir atsiskaitymo puslapyje.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'Suderinkite krepšelio išdėstymą su atsiskaitymo puslapiu, kad pirkimo procesas būtų nuoseklus.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'Užtikrinkite, kad krepšelis visada būtų atnaujinamas fone – keičiantis prekių kiekiui, puslapis neturi būti perkraunamas iš naujo.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Pateikite kuponų kodus, informaciją apie pristatymą ir papildomus pasiūlymus būtent ten, kur jie duoda geriausius rezultatus.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Slinkdami puslapį, užtikrinkite, kad užsakymo santrauka liktų matoma, ir ten, kur pirkėjams reikia pasitikėjimo, įterpkite pasitikėjimo simbolius.','Columns' => 'Skiltys','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'Bendrieji stilių šablonai, skirti atsiskaitymo etapams, užsakymo santraukai ir kitoms sekcijoms. Taikomi kitiems atsiskaitymo, krepšelio, padėkos (užsakymas gautas) ir užsakymo peržiūros puslapiams.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'Naudojant <em>„1 stulpelis“</em> išdėstymą su <em>„Split“</em> dizaino šablonu, dešinysis stulpelis rodomas tik tuomet, jei puslapio šoninės juostos valdiklių sritis yra aktyvi („Checkout Sidebar“, „Cart Sidebar“ arba „Order Received Sidebar“). Kitais atvejais puslapis išlieka vieno stulpelio su „Split“ stiliais.','Split column background' => 'Stulpelio fono padalijimas','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'Pasirinkite „Split“ dizaino antrosios kolonos fono spalvą. Jei norite naudoti užsakymo santraukos fono spalvą, palikite laukelį tuščią.','Page templates' => 'Puslapių šablonai','Checkout template' => 'Atsiskaitymo šablonas','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Rekomenduojama, jei norite, kad atsiskaitymo metu būtų kuo mažiau trukdžių. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Perskaitykite tyrimą apie krepšelių apleidimą</a>.','Sticky progress bar' => 'Prisitvirtinanti pažangos juosta','Progress bar style' => 'Pažangos juostos stilius','Order totals' => 'Užsakymų sumos','Background color' => 'Fono spalva','Action link' => 'Veiksmo nuoroda','Mobile order summary' => 'Mobiliojo užsakymo santrauka','Mobile initial state' => 'Mobiliojo įrenginio pradinė būsena','Enable editing cart items at checkout' => 'Įjungti prekių krepšelio elementų redagavimą atsiskaitant','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Leiskite klientams keisti prekių kiekius arba pašalinti prekes tiesiogiai atsiskaitymo puslapyje.','Cart item errors' => 'Krepšelio prekių klaidos','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Taikoma tik tuomet, kai kupono kodas rodomas kaip atskiras skyrius atsiskaitymo arba krepšelio puslapiuose ir jei „WooCommerce“ nustatymuose įjungta galimybė naudoti kupono kodus.','Coupon codes position' => 'Kuponų kodų vieta','Apply coupon button' => 'Mygtukas „Taikyti kuponą“','Select style of the "apply coupon" button.' => 'Pasirinkite mygtuko „Taikyti kuponą“ stilių.','Address line 2' => '2-oji adreso eilutė','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'Šis nustatymas taikomas tiek skyriui „Atsiskaitymas“, tiek skyriui „Paėmimas vietoje“. Skyriuje „Paėmimas vietoje“ jis taip pat lemia, ar pasirinkimo laukelis „Pristatymas / Paėmimas“ bus rodomas pristatymo būdų skyriuje (prieš adresą) ar kaip atskiras skyrius (po jo).','Customer accounts' => 'Klientų sąskaitos','Guest checkout' => 'Atsiskaitymas kaip svečiui','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => '„WooCommerce“ paskyrų nustatymų puslapyje esančios parinktys, susijusios su atsiskaitymu kaip svečias, prisijungimu ir paskyros kūrimu. Jos čia tvarkomos jūsų patogumui, kad galėtumėte naudoti skirtingas reikšmes kiekvienam nustatymų profiliui.','Allow customers to checkout without an account' => 'Leisti klientams atsiskaityti be paskyros','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>Rekomenduojama</strong>, kad klientams atsiskaitant nebūtų prašoma susikurti paskyros ar prisijungti, nes tai gali sumažinti konversijos rodiklius.','When disabled, customers must log in or create an account to complete the purchase.' => 'Jei ši funkcija išjungta, klientai, norėdami užbaigti pirkimą, turi prisijungti arba susikurti paskyrą.','Login at checkout' => 'Prisijunkite atsiskaitydami','Enable log-in during checkout' => 'Įjungti prisijungimą atsiskaitant','Show a link for returning customers to log in from the checkout page.' => 'Atsiskaitymo puslapyje parodykite nuorodą, kuria nuolatiniai klientai galėtų prisijungti.','Account creation' => 'Paskyros sukūrimas','Allow customers to create an account during checkout' => 'Leisti klientams susikurti paskyrą atsiskaitant','Customers can create an account before placing their order.' => 'Klientai gali susikurti paskyrą prieš pateikdami užsakymą.','Allow customers to create an account from the My account page' => 'Leiskite klientams susikurti paskyrą puslapyje „Mano paskyra“','Customers can register a new account from the My account page.' => 'Klientai gali susikurti naują paskyrą puslapyje „Mano paskyra“.','Username' => 'Vartotojo vardas','Generate from customer\'s name' => 'Sukurti pagal kliento vardą','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>Rekomenduojama</strong>, kad klientams atsiskaitant nebūtų prašoma pasirinkti vartotojo vardo, nes tai gali sumažinti konversijos rodiklius.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'Vartotojo vardas sugeneruojamas pagal kliento vardą arba, jei vardo negalima naudoti, pagal elektroninio pašto adresą.','Password' => 'Slaptažodis','Send password setup link' => 'Siųsti nuorodą slaptažodžiui nustatyti','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>Rekomenduojama</strong>, kad klientams atsiskaitant nebūtų prašoma nustatyti slaptažodžio, nes tai gali sumažinti konversijos rodiklius.','Customers receive an email to create their password securely.' => 'Klientai gauna el. laišką, kuriame nurodoma, kaip saugiai sukurti slaptažodį.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Leiskite registruotiems klientams užbaigti pirkimo procesą neprisijungus ir susieti užsakymą su jų esama paskyra, jei kontaktiniai duomenys sutampa.','Existing account message' => 'Pranešimas apie esamą sąskaitą','Let customers create an account after placing their order, from the thank you page.' => 'Leiskite klientams susikurti paskyrą po užsakymo pateikimo, iš „Ačiū“ puslapio.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'Šio skirsnio parinktys yra prieinamos, kai įjungtas atsiskaitymas kaip svečias ir paskyrų suderinimas. Įjunkite abi minėtas funkcijas, kad nustatytumėte atidėtą paskyros sukūrimą.','Enable delayed account creation' => 'Įjungti atidėtą paskyros kūrimą','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'Įjunkite atidėtą paskyros kūrimą, kai įjungtos tiek atsiskaitymo kaip svečias, tiek paskyrų atitikimo funkcijos.','Section position' => 'Skyriaus pareigos','Before customer details section' => 'Prieš skyrių „Kliento duomenys“','After customer details section' => 'Po skyriaus „Kliento duomenys“','Account creation benefits' => 'Sąskaitos sukūrimo privalumai','Leaving the field empty will display the default text.' => 'Jei lauką paliksite tuščią, bus rodomas numatytasis tekstas.','Inline buttons' => 'Įterptieji mygtukai','Required fields' => 'Privalomi laukeliai','Enable gift message fields at checkout' => 'Įjunkite dovanų žinučių laukelius atsiskaitymo metu','Expanded gift message' => 'Išplėstinis dovanos pranešimas','Display gift message field always expanded' => 'Laukelis „Dovanos žinutė“ visada rodomas išskleistas','Gift message in order details' => 'Dovanos žinutė užsakymo duomenyse','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'Šiuo metu šiame skyriuje nėra jokių integracijų. Su kiekvienu papildiniu ir tema susijusios parinktys čia pasirodys tik tada, kai tas papildinys ar tema bus aktyvuoti.','Phone fields' => 'Telefono laukeliai','Field visibility' => 'Lauko matomumas','Field position' => 'Padėtis aikštėje','Phone country code & validation' => 'Telefono šalies kodas ir patikrinimas','Country' => 'Šalis','Enable country on phone fields' => 'Įjungti šalies pasirinkimą telefono laukeliuose','Filter countries for shipping or billing' => 'Filtruoti šalis pagal pristatymą arba sąskaitos išrašymą','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Kiekviename telefono laukelyje šalies pasirinkimo galimybes apribokite tik tomis šalimis, į kurias jūsų parduotuvė leidžia siųsti prekes arba kuriose leidžiama išrašyti sąskaitas.','Validation' => 'Patikrinimas','Enable simple validation based on country rules' => 'Įjungti paprastą tikrinimą pagal šalies taisykles','Checks that the phone number is valid for the selected country, including country code and length.' => 'Patikrina, ar telefono numeris yra galiojantis pasirinktoje šalyje, įskaitant šalies kodą ir simbolių skaičių.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'Atlikti griežtesnę patikrą, ar numeris yra galiojantis mobiliojo ryšio, fiksuotojo ryšio ar kito leidžiamo tipo numeris pasirinktoje šalyje. Gali būti atmesti kai kurie galiojantys numeriai.','Validation types' => 'Patvirtinimo tipai','Placeholders' => 'Vietos laikikliai','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'Šiuo metu nėra licencijų raktų, kuriuos reikėtų valdyti. Licencijų raktai čia pasirodys, kai bus aktyvuotas licencijuotas „Fluid Checkout“ įskiepis arba papildinys.','Default delivery type' => 'Numatytasis pristatymo būdas','Choose which delivery type will be selected by default.' => 'Pasirinkite, koks pristatymo būdas bus nustatytas kaip numatytasis.','Shipping zone fields' => 'Pristatymo zonos laukeliai','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Pasirinkite, kurie laukeliai bus rodomi kaip vietinio paėmimo pristatymo zonos filtravimo laukeliai. Palikite tuščius, jei norite rodyti visas galimas parinktis.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Šie laukeliai bus rodomi kaip vietinio atsiėmimo pristatymo būdų filtras. Kai kurie laukeliai vis tiek gali būti rodomi atsiskaitymo metu, net jei čia jie nebuvo pažymėti, jei suderinami įskiepiai reikalauja jų, kad veiktų tinkamai.','Order shipping address' => 'Užsakymo pristatymo adresas','Order pay page optimization' => 'Užsakymo apmokėjimo puslapio optimizavimas','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'Neapmokėtiems užsakymams suteikite tokį pat aiškų, į konversiją orientuotą išdėstymą kaip ir atsiskaitymo puslapyje.','Optimize the layout of the order pay page for orders pending payment.' => 'Optimizuokite užsakymų, kurių apmokėjimas dar neatliktas, apmokėjimo puslapio išdėstymą.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'Suderinkite užsakymo apmokėjimo procesą su atsiskaitymo etapu, kad pirkimo procesas būtų nuoseklus.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Įdėkite pasitikėjimo simbolius ir ženklus ten, kur pirkėjams prieš atsiskaitant reikia užtikrinimo.','Thank you page optimization' => '„Ačiū“ puslapio optimizavimas','Make the thank you page and order details clearer for customers after they buy.' => 'Padarykite, kad padėkos puslapis ir užsakymo informacija būtų aiškesni klientams po pirkimo.','Optimize the thank you page and account order details with a clearer layout.' => 'Optimizuokite padėkos puslapį ir užsakymo duomenis paskyroje, suteikdami jiems aiškesnį išdėstymą.','Show order status progress, actions, downloads, and notes where they make sense.' => 'Ten, kur tai yra tikslinga, rodykite užsakymo būsenos pažangą, veiksmus, atsisiuntimus ir pastabas.','Customize order details sections on email notifications.' => 'Pritaikyti užsakymo duomenų skyrius el. pašto pranešimuose.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Įdėkite pasitikėjimo simbolius ir ženklus ten, kur pirkėjams reikia užtikrinimo po pirkimo.','Email notifications' => 'Pranešimai el. paštu','Enable thank you page and order details optimizations to see more options' => 'Įjunkite padėkos puslapio ir užsakymo duomenų optimizavimą, kad galėtumėte peržiūrėti daugiau parinkčių','Use wide layout on thank you page' => 'Padėkos puslapyje naudokite platų išdėstymą','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Šios parinktys turi įtakos padėkos puslapiui, užsakymo duomenų peržiūrai paskyros puslapiuose ir el. pašto pranešimuose.','Save settings' => 'Išsaugoti nustatymus','Docs' => 'Dokumentai','Cart' => 'Krepšelis','Thank you' => 'Ačiū','Address autocomplete' => 'Adresų automatinis užpildymas','Trust badges' => 'Pasitikėjimo ženklai','You do not have permission to save these settings.' => 'Jūs neturite leidimo išsaugoti šių nustatymų.','Invalid save request.' => 'Neteisingas išsaugojimo prašymas.','Your settings have been saved.' => 'Jūsų nustatymai buvo išsaugoti.','Saving...' => 'Įrašoma...','Settings could not be saved. Please try again.' => 'Nepavyko išsaugoti nustatymų. Prašome bandyti dar kartą.','Dismiss notice' => 'Atmesti pranešimą','Open settings menu' => 'Atidaryti nustatymų meniu','Close settings menu' => 'Uždaryti nustatymų meniu','Preview' => 'Peržiūra','Expand preview' => 'Išplėsti peržiūrą','Collapse preview' => 'Sutraukti peržiūrą','Show header and footer' => 'Rodyti antraštę ir apačią','Hide header and footer' => 'Paslėpti antraštę ir apačią','Page preview' => 'Puslapio peržiūra','Preview viewport' => 'Peržiūros lango peržiūra','Tablet' => 'Planšetinis kompiuteris','Desktop' => 'Darbalaukis','Preview width' => 'Peržiūros plotis','Decrease width' => 'Sumažinti plotį','Preview width in pixels' => 'Peržiūros plotis pikseliais','Increase width' => 'Padidinti plotį','Preview as' => 'Peržiūrėti kaip','Guest' => 'Svečias','Logged in' => 'Prisijungęs','Preview page' => 'Puslapio peržiūra','Expand preview for a closer look' => 'Išskleiskite peržiūrą, kad galėtumėte geriau įsižiūrėti','Available with %s.' => 'Galima įsigyti su %s.','Turn them on' => 'Įjunkite juos','Optimizations for this page are turned off. %s to preview the page.' => 'Šio puslapio optimizavimas yra išjungtas. %s, kad peržiūrėtumėte puslapį.','%s preview' => '%s peržiūra','Isolated session · nothing is saved' => 'Atskira sesija · niekas nėra išsaugoma','Usage tracking' => 'Naudojimo stebėjimas','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Siųskite neslaptas svetainės aplinkos ataskaitas, kad padėtumėte „Fluid Checkout“ pagerinti suderinamumą. Ataskaitos nebus siunčiamos, kol tai nebus įjungta žemiau pateiktose parinktyse.','Send usage tracking reports to Fluid Checkout' => 'Siųsti naudojimo stebėjimo ataskaitas į „Fluid Checkout“','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'Šios ataskaitos padeda mums gerinti suderinamumą ir jūsų svetainės palaikymą; jei ši funkcija įjungta, ataskaitos siunčiamos kas savaitę.','No customer, admin user, or any other sensitive data is included in the reports.' => 'Ataskaitose nėra pateikiama jokių klientų, administratorių ar kitų konfidencialių duomenų.','Basic environment info' => 'Pagrindinė informacija apie aplinką','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'Duomenys apie „WordPress“, PHP, „WooCommerce“, šabloną ir papildinių sąrašą. Visada įtraukiami, kai įjungta ataskaitų funkcija. Tai padeda mums suprasti aplinką, kurioje veikia jūsų svetainė.','Plugin settings' => 'Įskiepio nustatymai','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'Siunčia „Fluid Checkout“ įskiepio nustatymus, kad palengvintų pagalbos užklausų tvarkymą ir padėtų mums suprasti, kaip naudojate mūsų įskiepius.','Coming soon' => 'Netrukus','Sales metrics' => 'Pardavimų rodikliai','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'Mėnesinis užsakymų skaičius ir bendros pardavimo pajamos per vienerius metus nuo „Fluid Checkout“ įdiegimo iki šiandien. Tai padeda mums suprasti, ar jūs uždirbate daugiau pinigų, kai įdiegti mūsų papildiniai. Jokių klientų ar vartotojų duomenų niekada nesiunčiama.','Utilities' => 'Komunalinės paslaugos','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'Vietoj <code>select2</code> naudokite <code>TomSelect</code> išskleidžiamųjų sąrašų komponentus','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => '„TomSelect“ – tai paprastesnis išskleidžiamasis pasirinkimo komponentas, kuris yra mažiau linkęs į klaidas nei „Select2“, tačiau siūlo tą pačią funkcionalumą.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'Šio įskiepio optimizuotuose puslapiuose nustato formos laukelių šrifto dydį iki 16 pikselių, kad mažuose įrenginiuose sąveikaujant su formos laukeliais nebūtų automatiškai didinamas vaizdas.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => '„Safari“ ir kitos naršyklės mobiliajame įrenginyje gali automatiškai padidinti vaizdą, kad tekstą būtų lengviau skaityti, kai šrifto dydis yra mažesnis nei 16 pikselių.','Enable script processing tracking on the browser console.' => 'Įjunkite skriptų vykdymo stebėjimą naršyklės konsolėje.','Unminified assets' => 'Nesuspausti ištekliai','Google Maps scripts' => '„Google Maps“ skriptai','Do not remove duplicate Google Maps scripts' => 'Nešalinkite pasikartojančių „Google Maps“ skriptų','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Kai ši parinktis įjungta, pasikartojantys „Google Maps“ skriptai NEBUS pašalinti, o tai gali sukelti klaidų ir veikimo sutrikimų. Šią parinktį naudokite tik trikčių šalinimo metu.','Widget areas' => 'Valdiklių sritys','Last step on mobile' => 'Paskutinis žingsnis mobiliajame įrenginyje','Display widgets only at last step on mobile' => 'Mobiliajame įrenginyje rodyti valdiklius tik paskutiniame žingsnyje','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'Mobiliajame įrenginyje rodyti atsiskaitymo patikimumo ženklo valdiklius tik tada, kai peržiūrimas paskutinis atsiskaitymo etapas','Standard' => 'Standartinis','VAT number field' => 'PVM kodo laukas','Add a VAT number field to the billing form.' => 'Į sąskaitos faktūros formą įtraukite PVM kodo laukelį.','Field label' => 'Lauko pavadinimas','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'Nustatykite PVM numerio laukelio pavadinimą (t. y. „PVM numeris“). Daugiakalbėse svetainėse geriau palikti šį laukelį tuščią ir išversti originalų tekstą.','VAT Number' => 'PVM kodas','EU-VAT' => 'ES PVM','Enable the VAT number field to see more options' => 'Įjunkite PVM kodo laukelį, kad galėtumėte matyti daugiau parinkčių','VAT validation' => 'PVM patvirtinimas','Validate VAT number field for EU-VAT during checkout' => 'Atsiskaitymo metu patikrinti laukelį „ES PVM kodas“','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Patikrina, ar pateiktas PVM kodas yra galiojantis PVM kodas, įregistruotas Europos VIES duomenų bazėje (PVM informacijos mainų sistema).','Shop VAT number' => 'Parduotuvės PVM kodas','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'Parduotuvės PVM kodas, naudojamas prašant patvirtinti ES PVM, ir nurodytas sąskaitose-faktūrose. <br><strong>Labai rekomenduojame įvesti savo parduotuvės PVM kodą</strong>, nes priešingu atveju VIES paieškos rezultatai gali būti nepripažįstami apskaitos tikslais. <br>Pvz.: <code>ATU99999999</code> arba <code>EE999999999</code>.','Reverse charge' => 'Atsakingumo perkėlimas','Apply reverse charge mechanism' => 'Taikyti atvirkštinio apmokestinimo mechanizmą','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Nustatykite mokesčio tarifą lygų nuliui ir sąskaitose faktūrose nurodykite „Atvirkštinis apmokestinimas“, jei kliento PVM kodas yra galiojantis. Priklausomai nuo parduotuvės šalies, gali būti reikalingas kitoks „Atvirkštinis apmokestinimas“ tekstas.','Same country' => 'Ta pati šalis','Apply reverse charge mechanism for transactions in the shop country:' => 'Parduotuvės šalyje vykdomiems sandoriams taikyti atvirkštinio apmokestinimo mechanizmą:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Leidžia taikyti atvirkštinio apmokestinimo mechanizmą sandoriams tarp įmonių, esančių toje pačioje šalyje kaip ir parduotuvė.','Reverse charge exceptions' => 'Išimtys, susijusios su atvirkštiniu apmokestinimu','Select additional countries to skip applying the reverse charge mechanism.' => 'Pasirinkite kitas šalis, kuriose netaikomas atvirkštinio apmokestinimo mechanizmas.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'Už užsakymus iš šių šalių bus taikomi mokesčiai net ir tuo atveju, jei bus pateiktas galiojantis PVM kodas.','Reverse charge label on invoices' => 'Sąskaitose faktūrose nurodyta atvirkštinio apmokestinimo nuoroda','Set the label of "reverse charge" on the checkout page and order details.' => 'Atsiskaitymo puslapyje ir užsakymo duomenyse nustatykite žymą „atvirkštinis apmokestinimas“.','Reverse charge text on invoices' => 'Tekstas apie atvirkštinį apmokestinimą sąskaitose-faktūrose','Set the label of "reverse charge" text on invoices.' => 'Nustatykite sąskaitose faktūrose esančio teksto „atvirkštinis apmokestinimas“ pavadinimą.','Tax to be paid on reverse charge basis' => 'Mokestis, mokėtinas taikant atvirkštinio apmokestinimo principą','Company name' => 'Įmonės pavadinimas','Autocomplete company name from VAT number' => 'Įmonės pavadinimo automatinis užpildymas pagal PVM kodą','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Įrašykite sąskaitą išrašančios įmonės pavadinimą, remdamiesi kliento pateiktu galiojančiu PVM kodu.','Company name editing' => 'Įmonės pavadinimo redagavimas','Allow editing of auto-filled company name' => 'Leisti redaguoti automatiškai įvestą įmonės pavadinimą','When enabled, customers can change the company name associated with the provided VAT number.' => 'Kai ši funkcija įjungta, klientai gali keisti įmonės pavadinimą, susietą su nurodytu PVM numeriu.','EU-VAT for digital goods' => 'ES PVM skaitmeninėms prekėms','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'Nuo 2015 m. sausio 1 d. buvo pakeisti ES PVM reglamentai, susiję su skaitmeninėmis prekėmis, ir šie pakeitimai taikomi tik B2C sandoriams. PVM už skaitmenines prekes turi būti apskaičiuojamas atsižvelgiant į kliento buvimo vietą, o tai patvirtinantys duomenys (IP adresas ir sąskaitos faktūros adresas) turi būti surinkti.','Tax classes for digital goods' => 'Skaitmeninių prekių mokesčių klasės','Select some tax classes' => 'Pasirinkite keletą mokesčių klasių','Location evidence' => 'Įrodymai dėl buvimo vietos','Collect customer\'s location evidence' => 'Surinkite įrodymus apie kliento buvimo vietą','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'Išsaugo IP adresą ir patikrina, ar jis atitinka kliento sąskaitos faktūros adresą. Jei kliento sąskaitos faktūros adreso šalis ir IP adresas nesutampa, klientas privalo patvirtinti savo sąskaitos faktūros adresą, pažymėdamas atitinkamą langelį atsiskaitymo puslapyje.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'Ši parinktis valdoma „Fluid Checkout“ sistemoje. <a href="%s">Ją galima pakeisti klientų paskyrų nustatymuose</a>.','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'Ši parinktis valdoma „Fluid Checkout“ sistemoje. Ją galite pakeisti skyriuje „Fluid Checkout“ > „Klientų paskyros“.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Ši parinktis valdoma „Fluid Checkout“ sistemoje. Kai „Fluid Checkout“ yra aktyvuota, pristatymo vieta visada nustatoma kaip „Pagal nutylėjimą – kliento pristatymo adresas“. Klientai vis tiek gali nurodyti skirtingus pristatymo ir sąskaitos išrašymo adresus atsiskaitymo metu.<br><br>Parinktis, leidžianti nustatyti, kad numatytasis sąskaitos išrašymo adresas sutaptų su pristatymo adresu, yra prieinama <a href="%s">„Fluid Checkout“ nustatymuose</a>.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Ši parinktis nustatoma „Fluid Checkout“ sistemoje. Kai „Fluid Checkout“ yra aktyvuota, pristatymo vieta visada nustatoma kaip „Pagal numatytąjį kliento pristatymo adresą“. Klientai vis tiek gali nurodyti kitus pristatymo ir sąskaitos išrašymo adresus atsiskaitymo metu.<br><br>Parinktis, leidžianti nustatyti, kad numatytasis sąskaitos išrašymo adresas sutaptų su pristatymo adresu, yra prieinama meniu „WooCommerce“ > „Nustatymai“ > „Fluid Checkout“.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Šie nustatymai buvo perkelti į „WP Admin“ > „Fluid Checkout“ > „Nustatymai“.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'Šis „WooCommerce“ nustatymų skirtukas yra pasenęs ir bus pašalintas „Fluid Checkout 6.0“ versijoje.','Go to settings page' => 'Eiti į nustatymų puslapį','Hide this tab permanently' => 'Visam laikui paslėpti šį skirtuką','Site report preview' => 'Svetainės ataskaitos peržiūra','This is the data that would be included in the next site environment report based on your current settings.' => 'Tai yra duomenys, kurie, remiantis jūsų dabartiniais nustatymais, būtų įtraukti į kitą svetainės aplinkos ataskaitą.','Loading report preview...' => 'Įkeliama ataskaitos peržiūra...','Could not load the site report preview. Try again.' => 'Nepavyko įkelti svetainės ataskaitos peržiūros. Bandykite dar kartą.','Could not send the site report. Try again.' => 'Nepavyko išsiųsti svetainės ataskaitos. Bandykite dar kartą.','Site report sent successfully.' => 'Svetainės ataskaita sėkmingai išsiųsta.','Enable and send now' => 'Įjunkite ir išsiųskite dabar','Close' => 'Uždaryti','A site report request is already in progress. Try again in a moment.' => 'Prašymas pateikti ataskaitą apie objektą jau nagrinėjamas. Prašome pabandyti vėliau.','Site environment reporting is disabled.' => 'Ataskaitų apie svetainės aplinką pateikimas yra išjungtas.','No site report data is available to send.' => 'Nėra jokių svetainės ataskaitos duomenų, kuriuos būtų galima nusiųsti.','This site domain cannot send environment reports (local or development domains are excluded).' => 'Šio svetainės domeno aplinkos ataskaitos negali būti siunčiamos (išskyrus vietinius arba kūrimo domenus).','A site report was sent recently. Try again later.' => 'Neseniai buvo išsiųsta ataskaita apie objektą. Pabandykite vėliau.','The site report could not be sent. Try again later.' => 'Nepavyko išsiųsti svetainės ataskaitos. Pabandykite vėliau.','Site environment reporting is not available.' => 'Ataskaitos apie objekto aplinką nėra pateiktos.','No site report data is available for the selected settings.' => 'Pagal pasirinktus parametrus nėra jokių vietovės ataskaitos duomenų.','You are not allowed to manage site reports.' => 'Jums neleidžiama tvarkyti svetainės ataskaitų.','PRO feature' => '„PRO“ funkcija','Other plugins' => 'Kiti papildiniai','Get only this add-on &mdash; %s' => 'Įsigykite tik šį papildinį — %s','Install add-on' => 'Įdiegti papildinį','Upgrade to PRO &mdash; %s' => 'Pereikite prie PRO versijos — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">Įsigykite %2$s</a>, kad galėtumėte naudotis šiomis funkcijomis.','Add-on' => 'Papildinys','View documentation' => 'Peržiūrėti dokumentaciją','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'Užklausoms reikalingas prisijungęs „WordPress“ vartotojas. Jei norite naudoti dabartinio vartotojo duomenis, praleiskite „user_id“ parametrą, arba nurodykite „user_id“, kad užklausa būtų nukreipta į kitą paskyrą, jei užklausos autorius turi teisę redaguoti tą vartotoją (teisė „edit_user“). Neautentifikuotos užklausos grąžina kodą „fc_api_forbidden“. Neteisingas „user_id“ grąžina klaidą „fc_api_user_not_found“.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 su { „data“: { ... } }, kai tvarkyklė grąžina duomenų bloką.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 su { „success“: true }, kai nėra duomenų (pavyzdžiui, DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'Klaidos grąžina „WordPress REST“ klaidos JSON duomenis iš „WP_Error“ (kodas, pranešimas, data.status). „Wire“ kodai naudoja priešdėlį „fc_api_*“.','Forbidden access.' => 'Įėjimas draudžiamas.','Target user was not found.' => 'Nerastas tikslinis vartotojas.','This feature is not available.' => 'Ši funkcija nėra prieinama.','A required address field is missing.' => 'Trūksta privalomo adreso laukelio.','Postcode or ZIP is invalid.' => 'Pašto kodas arba ZIP kodas yra neteisingas.','Phone number is invalid.' => 'Telefono numeris neteisingas.','State or county is invalid.' => 'Valstija arba apskritis nurodyta neteisingai.','Country is invalid or has no address fields.' => 'Šalis neteisinga arba neturi adresų laukelių.','The request could not be processed.' => 'Prašymo nebuvo galima apdoroti.','Back to previous step' => 'Grįžti į ankstesnį žingsnį','Skip to settings' => 'Pereiti prie nustatymų','Start over and return to the first guided setup step' => 'Pradėkite iš naujo ir grįžkite prie pirmojo nustatymo žingsnio su gidu','Start over' => 'Pradėti iš naujo','Please complete all sub-steps before continuing.' => 'Prieš tęsdami, atlikite visus tarpinius veiksmus.','Expand' => 'Išskleisti','Collapse' => 'Sutraukti','Skip' => 'Praleisti','Mark as complete' => 'Pažymėti kaip užbaigtą','Mark as incomplete' => 'Pažymėti kaip nebaigtą','View full-size image: %s' => 'Peržiūrėti vaizdą pilnu dydžiu: %s','Full-size setup guide image' => 'Pilno dydžio sąrankos vadovo paveikslėlis','Close image' => 'Uždaryti paveikslėlį','Fluid Checkout Guided Setup' => '„Fluid Checkout“ nustatymo vadovas','Welcome' => 'Sveiki atvykę','Explore your checkout' => 'Peržiūrėkite savo užsakymą','All set' => 'Viskas paruošta','You do not have permission to access this page.' => 'Jūs neturite leidimo pasiekti šį puslapį.','Go to step %1$d: %2$s' => 'Eikite į %1$d žingsnį: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'Šis žingsnis po žingsnio nustatymo vadovas padės jums susipažinti su „Fluid Checkout“. Toliau pateikti žingsniai kol kas yra tik pavyzdiniai.','Continue to the next step when you are ready.' => 'Kai būsite pasirengę, pereikite prie kito žingsnio.','Open your store checkout to see Fluid Checkout in action.' => 'Atidarykite savo parduotuvės atsiskaitymo puslapį, kad pamatytumėte, kaip veikia „Fluid Checkout“.','View checkout page' => 'Peržiūrėti atsiskaitymo puslapį','You can return to Fluid Checkout settings to continue configuring your store.' => 'Galite grįžti į „Fluid Checkout“ nustatymus ir toliau konfigūruoti savo parduotuvę.','Review checkout and cart settings' => 'Peržiūrėkite atsiskaitymo ir krepšelio nustatymus','Explore add-ons from the dashboard' => 'Išbandykite papildinius iš valdymo skydo','Finish & go to settings' => 'Baigti ir pereiti prie nustatymų','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Atnaujinkite sąskaitų išrašymo telefono lauko matomumo parinktį, pakeisdami senąją reikšmę taip, kad ji atitiktų „WooCommerce“ taisykles.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Atnaujinkite siuntimo telefono laukelio matomumo parinktį, pakeisdami senąją reikšmę taip, kad ji atitiktų „WooCommerce“ taisykles.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'Nukopijuokite užsakymo santraukos fono spalvos nustatymą į naują „Split“ dizaino antrinės kolonos fono spalvos parinktį.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'Naudojant „Biteship“ įskiepį, išplėstinė laukelių pasirinkimo funkcija visada yra išjungta.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Naudojant „German Market“ įskiepį, užsakymo pateikimo vieta visada nustatoma kaip „Po užsakymo santraukos“. Šis įskiepis reikalauja, kad užsakymo pateikimo mygtukas ir privalomi pažymėti langeliai būtų rodomi po užsakymo santraukos.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'Naudojant „Germanized for WooCommerce“ įskiepį, užsakymo pateikimo vieta visada nustatoma kaip „Po užsakymo santraukos“. Šis įskiepis reikalauja, kad užsakymo pateikimo mygtukas ir privalomi pažymėti langeliai būtų rodomi po užsakymo santraukos.','Edit pickup locations' => 'Redaguoti paėmimo vietas','Use local pickup label from WooCommerce settings' => 'Naudokite vietinio atsiėmimo etiketę iš „WooCommerce“ nustatymų','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'Kai ši funkcija įjungta, atsiskaitymo metu rodomas paėmimo parinkties pavadinimas atitinka pavadinimą, nurodytą „WooCommerce“ paėmimo vietos nustatymuose. Kai ši funkcija išjungta, pavadinime naudojamas iš „Fluid Checkout“ paimtas verčiamas tekstas „Paėmimas vietoje“.','Button label for applying coupon codesApply' => 'Taikyti','Checkout step titleContact' => 'Susisiekite su','Checkout step titleShipping' => 'Pristatymas','Checkout step titleBilling' => 'Atsiskaitymas','Checkout step titlePayment' => 'Mokėjimas','Checkout substep change link labelChange' => 'Keisti','Checkout substep save link labelSave changes' => 'Išsaugoti pakeitimus','Substep review textNone.' => 'Nėra.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'Nepasirinktas joks vaizdas.','Settings sectionCart' => 'Krepšelis','Settings sectionOrder pay' => 'Užsakymo apmokėjimas','Settings sectionThank you' => 'Ačiū','Settings section titleIntegrations' => 'Integracijos','Settings section titleLicense keys' => 'Licencijų raktai','Captcha positionBefore place order section' => 'Prieš pateikdami užsakymą skyriuje','Captcha positionBefore place order button' => 'Prieš užsakymo mygtuką','No shipping method chosen label for the order summary--' => '--','Close button aria-labelClose' => 'Uždaryti','Log in link label at checkout contact stepLog in' => 'Prisijungti','Log in separator label at for when guest checkout is disabledOr continue below' => 'Arba tęskite toliau','Log in separator label at for when guest checkout is disabledOr continue as a guest' => 'Arba tęskite kaip svečias','Clear image selection on admin pages.Remove image' => 'Pašalinti vaizdą','shipping packagesShipping %d' => 'Pristatymas %d','shipping packagesShipping' => 'Pristatymas','Used as fallback for "Proceed to next step" button labelnext step' => 'kitas žingsnis','Substep review checkbox valueYes' => 'Taip','Substep review checkbox line%1$s: %2$s' => '%1$s: %2$s','Dummy customer first name in the admin previewJohn' => 'Džonas','Dummy customer last name in the admin previewDoe' => 'Doe','Dummy customer company in the admin previewExample Company' => 'Pavyzdinė įmonė','Dummy customer street address in the admin preview123 Main Street' => '123 Pagrindinė gatvė','Dummy customer city in the admin previewAnytown' => 'Bet koks miestelis','Dummy order notes in the admin previewPlease leave the package at the front door.' => 'Prašome palikti siuntinį prie įėjimo durų.','Dummy product name in the admin previewBeanie' => 'Kepurė','Dummy product name in the admin previewCap' => 'Kepurė','Dummy product name in the admin previewT-Shirt' => 'Marškinėliai','Dummy order update in the admin previewWe received your order and will send you an update when it ships.' => 'Gavome jūsų užsakymą ir pranešime jums, kai jis bus išsiųstas.','Dummy download in the admin previewUser guide' => 'Naudojimo instrukcija','Google Places API versionsPlaces API (New)' => '„Places“ API (nauja)','Google Places API versionsPlaces API (Legacy)' => '„Places“ API (senoji versija)','Brasil API versionsVersion 1' => '1 versija','Brasil API versionsVersion 2' => '2 versija','Delayed account creation benefits placeholder text✔ Checkout faster next time
